gf = [d for d in data if len(d['gold'].get('entities', [])) > 0]
N = len(gf[0]['samples'])

# Try multiple rounding precisions
for prec in [4, 6, 8, 10, None]:
    n = 0
    for inst in gf:
        f1s = [per_instance_f1(s, inst['gold'], subtask='ner') for s in inst['samples']]
        if prec is None:
            if len(set(f1s)) == 1:
                n += 1
        else:
            if len(set(round(f, prec) for f in f1s)) == 1:
                n += 1
    print(f'N=16, prec={prec}: {n}/{len(gf)} = {n/len(gf):.4f} ({n/len(gf)*100:.1f}%)')

# Also try: max(f1s) - min(f1s) < threshold
for thresh in [0.001, 0.005, 0.01]:
    n = 0
    for inst in gf:
        f1s = [per_instance_f1(s, inst['gold'], subtask='ner') for s in inst['samples']]
        if max(f1s) - min(f1s) < thresh:
            n += 1
